using System;
using System.IO;
using System.Linq;
using System.Collections;
using TMPro;
using UnityEngine;
using Newtonsoft.Json.Linq;
namespace SpatialWallpaper.Blueprint {
 // Developer-only integration check through the actual UI event handlers.
 public sealed class BlueprintEditorCheck:MonoBehaviour {
  string output;JArray cases=new JArray();
  void Require(bool value,string name){if(!value)throw new Exception(name);cases.Add(name);}
  static void Click(string name){FindObjectsOfType<Evo.UI.Button>().Single(b=>b.name==name).onClick.Invoke();}
  static void Number(string name,string text){var field=FindObjectsOfType<TMP_InputField>().Single(f=>f.name=="Blueprint "+name);field.text=text;field.onEndEdit.Invoke(text);}
  IEnumerator Start(){output=BlueprintScene.Argument("--blueprint-editor-check");if(output==null)yield break;Directory.CreateDirectory(output);var run=Run();Exception failure=null;while(true){bool next;object current;try{next=run.MoveNext();current=next?run.Current:null;}catch(Exception e){failure=e;break;}if(!next)break;yield return current;}File.WriteAllText(Path.Combine(output,"editor-checks.json"),new JObject{["pass"]=failure==null,["standalone"]=!Application.isEditor,["simulated_eye_only"]=true,["cases"]=cases,["error"]=failure?.ToString()}.ToString());Application.Quit(failure==null?0:2);}
  IEnumerator Run(){var scene=FindObjectOfType<BlueprintScene>();float deadline=Time.realtimeSinceStartup+60;while(!scene.Ready&&scene.Error==null&&Time.realtimeSinceStartup<deadline)yield return null;Require(scene.Ready,"real-source-import");Require(scene.Settings.Terrain=="none","new-import-defaults-to-source-only");yield return new WaitForSeconds(.3f);Require(!GameObject.Find("ActualGround")&&!GameObject.Find("Template water")&&!scene.GetComponentsInChildren<Transform>().Any(t=>t.name.StartsWith("Tree ")),"source-only-has-no-template-ground-water-or-trees");Require(!FindObjectOfType<PoolPlanarReflection>(),"source-only-does-not-create-reflection-camera");Require(RenderSettings.skybox&&RenderSettings.skybox.shader.name=="Skybox/Farland Skies/Cloudy Crown"&&RenderSettings.skybox.GetTexture("_CloudsTex")&&RenderSettings.skybox.GetTexture("_StarsTex"),"procedural-clouds-and-stars-bound");Require(scene.Lighting.Pipelines.All(p=>p.additionalLightsRenderingMode==UnityEngine.Rendering.Universal.LightRenderingMode.PerPixel),"all-quality-tiers-use-per-pixel-local-lights");BlueprintEditorPanel.Open(scene);yield return null;
   Number("水平旋转","27");Require(scene.Settings.Yaw==27,"numeric-input-updates-content");Number("水平旋转","NaN");Require(scene.Settings.Yaw==27,"invalid-numeric-input-keeps-pose");
   Click("文件");yield return null;FindObjectsOfType<TMP_InputField>().Single(f=>f.name=="Blueprint work name").text="回归木屋 "+Guid.NewGuid().ToString("N").Substring(0,6);Click("保存");Require(scene.Work!=null,"save-through-real-button");var first=scene.Work;Require(File.Exists(BlueprintLibrary.Store.SourcePath(first.SourceHash)),"saved-source-independent-of-download");
   Click("另存为");Require(scene.Work.WorkId!=first.WorkId&&scene.Work.SourceHash==first.SourceHash,"save-as-separates-work-shares-source");var second=scene.Work;Require(BlueprintLibrary.Store.Revision(first.WorkId,first.RevisionId).Settings.Yaw==27,"first-work-remains-unchanged");
   Click("构图");yield return null;Number("左右位置","0.1");Require(Mathf.Abs(scene.Settings.OffsetX-.1f)<.0001f,"second-work-draft-can-change");Click("取消");yield return null;Require(!FindObjectOfType<BlueprintEditorPanel>()&&scene.Settings.OffsetX==0&&scene.Work.WorkId==second.WorkId,"cancel-restores-saved-revision");
   var load=scene.LoadPath(BlueprintLibrary.Store.SourcePath(first.SourceHash));while(!load.IsCompleted)yield return null;Require(scene.Ready&&scene.Document.BlockCount>0,"reload-from-preserved-source");scene.Work=first;scene.ApplySettings(first.Settings);
   BlueprintEditorPanel.Open(scene);yield return null;Click("环境");yield return null;yield return new WaitForSeconds(.4f);yield return new WaitForEndOfFrame();var tex=new Texture2D(Screen.width,Screen.height,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,Screen.width,Screen.height),0,0);tex.Apply();File.WriteAllBytes(Path.Combine(output,"environment-editor.png"),tex.EncodeToPNG());Destroy(tex);Click("取消");yield return null;
   Require(BlueprintLibrary.Works().Any(a=>a.Id==BlueprintLibrary.Artwork(first).Id),"saved-work-registered-in-existing-library");
   var pose=scene.Settings.Clone();pose.Terrain="waterfront";pose.Scale=1.45f;pose.Yaw=41;pose.OffsetX=.25f;pose.OffsetY=-.08f;scene.ApplySettings(pose);yield return new WaitForSeconds(.35f);var terrain=scene.GetComponent<BlueprintTerrain>();var footprint=BlueprintFootprint.For(scene.Document,scene.Placement,scene.Settings);Require(Mathf.Abs(terrain.LastFootprint.MaxX-footprint.MaxX)<.0001f&&terrain.PondBounds.xMin>footprint.MaxX,"terrain-follows-final-scale-yaw-and-position");var floor=GameObject.Find("ActualGround").GetComponent<Collider>();var origin=scene.transform.TransformPoint(new Vector3((footprint.MinX+footprint.MaxX)*.5f,2,(footprint.MinZ+footprint.MaxZ)*.5f));Require(floor.Raycast(new Ray(origin,Vector3.down),out var groundHit,10)&&scene.transform.InverseTransformPoint(groundHit.point).y<footprint.BaseY-.01f,"lowered-foundation-carves-ground-instead-of-cutting-building");Require(scene.GetComponentsInChildren<Transform>().Where(t=>t.name.StartsWith("Tree ")).All(t=>!footprint.Contains(t.localPosition.x,t.localPosition.z,4*scene.Placement.Scale)),"template-trees-avoid-final-building-footprint");scene.ApplySettings(first.Settings);yield return new WaitForSeconds(.3f);
   var cycle=scene.Settings.Clone();cycle.TimeMode="cycle";cycle.Hour=6;cycle.CycleMinutes=1;scene.ApplySettings(cycle);yield return new WaitForSeconds(.6f);Require(scene.CycleHour>6.15f,"runtime-cycle-advances-active-phase");BlueprintEditorPanel.Open(scene);yield return null;Click("环境");yield return null;Number("世界时间","19");Require(scene.CycleHour>=19&&scene.CycleHour<19.15f,"time-input-resets-running-cycle");Click("取消");yield return null;Require(scene.CycleHour>6&&scene.CycleHour<7,"cancel-restores-original-cycle-phase");
   BlueprintEditorPanel.Open(scene);yield return null;Click("环境");yield return null;Number("世界时间","19");Click("文件");yield return null;Click("保存");var cycleSaved=scene.Work;Require(cycleSaved.Settings.TimeMode=="cycle"&&cycleSaved.Settings.Hour>=19,"save-uses-visible-cycle-phase");Click("取消");yield return null;yield return new WaitForSeconds(.3f);float phaseBefore=scene.CycleHour;scene.Work=cycleSaved;var cycleReload=scene.LoadPath(scene.SourcePath);while(!cycleReload.IsCompleted)yield return null;Require(cycleReload.Result&&Mathf.Abs(scene.CycleHour-phaseBefore)<.15f,"reload-restores-local-playback-phase");scene.Work=first;scene.ApplySettings(first.Settings);

   var building=scene.Building;string preserved=scene.SourcePath;string invalid=Path.Combine(output,"invalid.schem");File.WriteAllBytes(invalid,new byte[]{1,2,3});var failure=scene.LoadPath(invalid);while(!failure.IsCompleted)yield return null;Require(!failure.Result&&scene.Ready&&scene.Building==building&&scene.SourcePath==preserved,"failed-import-keeps-active-geometry-and-source");
   BlueprintEditorPanel.Open(scene);yield return null;FindObjectsOfType<TMP_InputField>().Single(f=>f.name=="Blueprint work name").text="";Click("完成");yield return null;Require(FindObjectOfType<BlueprintEditorPanel>()!=null&&scene.Work.WorkId==first.WorkId,"failed-save-keeps-editor-and-old-work");Click("取消");yield return null;
  }
 }
}
